# =========================================================
# HELPER - SAFE TEXT
# =========================================================

def safe(value):

    if value is None:
        return ""

    return frappe.utils.escape_html(
        str(value)
    )


# =========================================================
# HELPER - DATE
# =========================================================

def format_date(value):

    if not value:
        return ""

    try:

        return frappe.utils.formatdate(
            value,
            "dd-MM-yyyy"
        )

    except Exception:

        return str(value)


