"""


# =========================================================
# REPORT DATE
# =========================================================

html = html + """

<div class="report-date">

Date: """ + safe(
    format_date(doc.date)
) + """

</div>

"""


# =========================================================
# MATERIAL
# =========================================================

html = html + """

<div class="info-row">

<span class="info-label">

Description of material

