"""


# =========================================================
# BRICK REPORT ITEMS
# =========================================================

items = doc.brick_report_items or []


if items:

    item = items[0]


    # =====================================================
    # SIZE
    # =====================================================

    html = html + """

<div class="info-row">

<span class="info-label">

Size

