<span class="info-value">

""" + safe(
        item.size
    ) + """

</span>

</div>

"""


    # =====================================================
    # MANUFACTURING DATE
    # =====================================================

    html = html + """

<div class="info-row">

<span class="info-label">

Batch no (Manufacturing Date)

</span>

<span class="info-colon">

:

</span>

<span class="info-value">

""" + safe(
        format_date(
            item.manufacturing_date
        )
    ) + """

</span>

</div>

"""


    # =====================================================
    # CUSTOMER + ADDRESS
    # =====================================================

    html = html + """

<div class="info-row">

<span class="info-label">

Customers Name & Address

</span>

<span class="info-colon">

:

</span>

<span class="info-value">

""" + safe(
        doc.customer
    ) + """

<br>

""" + safe(
        doc.customer_address
    ) + """

</span>

