"""


    # =====================================================
    # SALES INVOICE
    # =====================================================

    invoice_no = item.sales_invoice_no or ""

    invoice_date = item.sales_invoice_date or ""


    html = html + """

<div class="info-row">

<span class="info-label">

Sales Invoice No & Date

</span>

<span class="info-colon">

:

</span>

<span class="info-value">

""" + safe(
        invoice_no
    )


    if invoice_no and invoice_date:

        html = html + """

&nbsp;&nbsp;&nbsp; - &nbsp;&nbsp;&nbsp;

"""


    html = html + safe(
        format_date(
            invoice_date
        )
    ) + """

</span>

</div>

"""


else:

    # =====================================================
    # CUSTOMER IF NO ITEM
    # =====================================================

    html = html + """

<div class="info-row">

<span class="info-label">

Customers Name & Address

</span>

<span class="info-colon">

:

</span>

<span class="info-value">

""" + safe(
        doc.customer
    ) + """

<br>

""" + safe(
        doc.customer_address
    ) + """

</span>

</div>

"""


# =========================================================
# OBSERVATION OF TEST
# =========================================================

html = html + """

<div class="observation-title">

OBSERVATION OF TEST

</div>


<div class="test-heading">

Type of Test

</div>

"""


# =========================================================
# TEST OBSERVATIONS
# =========================================================

tests = doc.test_observations or []


test_number = 0


for test in tests:

    test_number = test_number + 1


    # =====================================================
    # LETTER
    # =====================================================

    if test_number == 1:

        letter = "a"

    elif test_number == 2:

        letter = "b"

    elif test_number == 3:

        letter = "c"

    elif test_number == 4:

        letter = "d"

    elif test_number == 5:

        letter = "e"

    elif test_number == 6:

        letter = "f"

    elif test_number == 7:

        letter = "g"

    elif test_number == 8:

        letter = "h"

    elif test_number == 9:

        letter = "i"

    else:

        letter = str(test_number)


    # =====================================================
    # GET RAW TEST DATA
    # =====================================================

    raw_data = test.get(
        "test_data"
    )


    observations = []


    # =====================================================
    # PARSE test_data
    #
    # IMPORTANT:
    # Do NOT use frappe.parse_json()
    #
    # json.loads() was confirmed working in
    # your Server Script environment.
    # =====================================================

    if raw_data:

        try:

            parsed_data = json.loads(
                raw_data
            )


            observations = (
                parsed_data.get(
                    "observations"
                )
                or []
            )


        except Exception:

            observations = []


    # =====================================================
    # TEST TYPE
    # =====================================================

    test_type = test.get(
        "test_type"
    ) or ""


    # =====================================================
    # SINGLE OBSERVATION
    #
    # Example:
    #
    # Weight Of Brick
    # weight : 27.98 kgs
    # =====================================================

    if len(observations) == 1:

        observation = observations[0]


        description = (
            observation.get(
                "description"
            )
            or test_type
            or ""
        )


        value = (
            observation.get(
                "value"
            )
            or ""
        )


        unit = (
            observation.get(
                "unit"
            )
            or ""
        )


        html = html + """

<div class="test-row">

""" + safe(
            letter
        ) + """) """

        html = html + safe(
            description
        )


        html = html + """

&nbsp;&nbsp;&nbsp; : &nbsp;&nbsp;&nbsp;

"""


        html = html + safe(
            value
        )


        if unit:

            html = html + """

&nbsp;

"""

            html = html + safe(
                unit
            )


        html = html + """

</div>

"""


    # =====================================================
    # MULTIPLE OBSERVATIONS
    #
    # Example:
    #
    # Compressive Strength (N/mm2)
    #
    # Test 1 : 9.23 N/mm^2
    # Test 2 : 9.42 N/mm^2
    # Test 3 : 9.26 N/mm^2
    # =====================================================

    else:


        # -------------------------------------------------
        # TEST TYPE
        # -------------------------------------------------

        html = html + """

<div class="test-row">

""" + safe(
            letter
        ) + """) """

        html = html + safe(
            test_type
        )

        html = html + """

</div>

"""


        # -------------------------------------------------
        # OBSERVATIONS
        # -------------------------------------------------

        observation_number = 0


        for observation in observations:

            observation_number = (
                observation_number + 1
            )


            description = (
                observation.get(
                    "description"
                )
                or (
                    "Test "
                    + str(
                        observation_number
                    )
                )
            )


            value = (
                observation.get(
                    "value"
                )
                or ""
            )


            unit = (
                observation.get(
                    "unit"
                )
                or ""
            )


            html = html + """

<div class="test-value">

"""


            html = html + safe(
                description
            )


            html = html + """

&nbsp;&nbsp;&nbsp; : &nbsp;&nbsp;&nbsp;

"""


            html = html + safe(
                value
            )


            if unit:

                html = html + """

&nbsp;

"""

                html = html + safe(
                    unit
                )


            html = html + """

</div>

"""


# =========================================================
# TEST DETAILS
# =========================================================

html = html + """

<div class="test-details">

"""


# =========================================================
# DATE OF TEST
# =========================================================

if tests:

    first_test = tests[0]


    html = html + """

<div class="info-row">

<span class="info-label">

Date of Test

</span>

<span class="info-colon">

:

</span>

<span class="info-value">

""" + safe(
        format_date(
            first_test.get(
                "date_of_test"
            )
        )
    ) + """

</span>

</div>

"""


