<div class="info-row">

<span class="info-label">

Test done by

</span>

<span class="info-colon">

:

</span>

<span class="info-value">

""" + safe(
    doc.test_done_by
) + """

</span>

</div>

"""


html = html + """

</div>

"""


# =========================================================
# FOOTER
# =========================================================

html = html + """

<div class="footer">

<div class="footer-company">

For """ + safe(
    company_name
) + """

</div>


<div class="footer-address">

Office address: """ + safe(
    office_address
) + """

</div>

</div>

"""


# =========================================================
# CLOSE HTML
# =========================================================

html = html + """

</body>

</html>

"""


# =========================================================
# DOWNLOAD WORD FILE
# =========================================================

frappe.response["filename"] = (
    "Brick Test Report - "
    + str(doc.name)
    + ".doc"
)


frappe.response["filecontent"] = html


frappe.response["type"] = "download"


frappe.response["content_type"] = (
    "application/msword"
)

# Supplier Quotation - temporarily set warehouse
# so ERPNext validation passes.
# Warehouse will be cleared before saving.

if doc.doctype == "Purchase Order":

    for row in doc.items:

        if row.item_code and not row.warehouse:

            # Get Item Default Warehouse for this Company
            warehouse = frappe.db.get_value(
                "Item Default",
                {
                    "parent": row.item_code,
                    "company": doc.company
                },
                "default_warehouse"
            )

            # If Item Default Warehouse is not configured,
            # use any active leaf warehouse belonging to the company.
            if not warehouse:
                warehouse = frappe.db.get_value(
                    "Warehouse",
                    {
                        "company": doc.company,
                        "is_group": 0,
                        "disabled": 0
                    },
                    "name"
                )

            if warehouse:
                row.warehouse = warehouse

# Clear warehouse before Supplier Quotation is saved.
# Supplier Quotation does not need a warehouse.

if doc.doctype == "Purchase Order":

    for row in doc.items:
        row.warehouse = None

if not doc.get("starting_time"):
    doc.starting_time = None

if not doc.get("ending_time"):
    doc.ending_time = None

if doc.doctype == "Purchase Order":
    # Fallback to Purchase Order Date or Today's Date if PO Required By is not set
    default_date = doc.schedule_date or doc.transaction_date or frappe.utils.nowdate()

    # Ensure parent schedule_date is set so mandatory validation passes
    if not doc.schedule_date:
        doc.schedule_date = default_date

    # Ensure child table row schedule_date is set so mandatory validation passes
    for row in doc.items:
        if not row.schedule_date:
            row.schedule_date = default_date

if doc.doctype == "Purchase Order":
    for row in doc.items:
        row.schedule_date = None

vehicle = frappe.form_dict.get("vehicle")
current_doc = frappe.form_dict.get("current_doc")

if vehicle:
    filters = {
        "vehicle": vehicle
    }

    if current_doc:
        filters["name"] = ["!=", current_doc]

    records = frappe.get_all(
        "Trip Sheet",
        filters=filters,
        fields=["name", "ending_odometer_reading"],
        order_by="creation desc",
        limit_page_length=1
    )

    if records:
        frappe.response["message"] = records[0].get("ending_odometer_reading") or 0
    else:
        frappe.response["message"] = 0
else:
    frappe.response["message"] = 0

# Convert Customer Name to uppercase
if doc.customer_name:
    doc.customer_name = doc.customer_name.upper()

# Convert GSTIN to uppercase
if doc.gstin:
    doc.gstin = doc.gstin.upper()
